const p2 = (g, x, y, c) => { if (x >= 0 && x < 16 && y >= 0 && y < 16) px(g, x, y, c); };

/* ---------- the districts' stone: five tones dark -> lit, a joint, an inlay ---------- */
export const DIST = {
