  for (let x = 0; x < W; x++) if (roofBot[x] === -2) { let d = 1; while (d < 60) { const a = x - d, b = x + d; const v = a >= 0 && roofBot[a] > -2 ? roofBot[a] : b < W && roofBot[b] > -2 ? roofBot[b] : -2; if (v > -2) { roofBot[x] = v; break; } d++; } }
