/* world-space smooth value noise */
const vn = (wx, wy, s) => { const x0 = Math.floor(wx / s), y0 = Math.floor(wy / s), fx = wx / s - x0, fy = wy / s - y0, h = (a, b) => (hash(a, b) % 1000) / 1000;
