/* ---------------------------------------------------------------- THE SAND ROOF: packed sand over buried roof tiles and beam ends */
function roofTile(x, y, o) {   /* o: gap (rows above the underside: 0 is the lowest row), aD, aL, aR (a shaft's lip) */
