// Only for a new, private 16x16 context before any overlay, clip or exposure.
// Each caller fills every pixel with opaque six-digit RGB before finishing.
// No canvas is cached or shared, and existing canvas ownership is unchanged.
export function opaqueTileFill(g) {
  const image = g.createImageData(16, 16), data = image.data;
  const colours = new Map();
  let last = '#000000', buffered = true;
  function flush() { if (buffered) { g.putImageData(image, 0, 0); g.fillStyle = last; } }
