    // Mutable exported palettes retain native CSS/invalid-colour behaviour.
    if (!buffered) { g.fillStyle = colour; g.fillRect(x | 0, y | 0, 1, 1); return; }
    let rgb = colours.get(colour);
    if (rgb === undefined) {
      if (typeof colour !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(colour)) {
        flush(); buffered = false;
        g.fillStyle = colour; g.fillRect(x | 0, y | 0, 1, 1); return;
      }
      rgb = parseInt(colour.slice(1), 16); colours.set(colour, rgb);
    }
    const i = ((y | 0) * 16 + (x | 0)) * 4;
    data[i] = rgb >>> 16; data[i + 1] = (rgb >>> 8) & 255;
    data[i + 2] = rgb & 255; data[i + 3] = 255; last = colour;
  }
  return {paint, finish: flush};
}

